window.__votdWeek && window.__votdWeek({"week":"2029-12-03","reading":"Doctrine and Covenants 137–138","days":[{"d":"2029-12-03","ref":"D&C 137:1","b":"D&C","c":137,"v":1,"he":"נִפְתְּחוּ הַשָּׁמַיִם עָלֵינוּ וָאֵרֶא אֶת־מַלְכוּת הַשָּׁמַיִם אֲשֶׁר לֵאלֹהִים וְאֶת כְּבוֹדָהּ אִם־בַּגּוּף אוֹ־מִחוּץ לַגּוּף לֹא אֵדָע׃","en":"The heavens were opened upon us, and I beheld the celestial kingdom of God, and the glory thereof, whether in the body or out I cannot tell."},{"d":"2029-12-04","ref":"D&C 137:6","b":"D&C","c":137,"v":6,"he":"וָאֶתְמַהּ אֵיךְ יָרַשׁ נַחֲלָה בַּמַּלְכוּת הַהִיא בְּרָאֹתִי כִּי מֵת מִן הַחַיִּים הָאֵלֶּה לִפְנֵי שְׁלֹחַ יְהוָה יָדוֹ לְקַבֵּץ אֶת־יִשְׂרָאֵל שֵׁנִית וְלֹא נִטְבַּל לִסְלִיחַת חֲטָאִים׃","en":"And marveled how it was that he had obtained an inheritance in that kingdom, seeing that he had departed this life before the Lord had set his hand to gather Israel the second time, and had not been baptized for the remission of sins."},{"d":"2029-12-05","ref":"D&C 137:7","b":"D&C","c":137,"v":7,"he":"וַיָּבֹא קוֹל יְהוָה אֵלַי לֵאמֹר כׇּל הַמֵּתִים בְּלֹא דַעַת הַבְּשׂוֹרָה הַזֹּאת אֲשֶׁר הָיוּ מְקַבְּלִים אוֹתָהּ לוּ הֻרְשׁוּ לְהִשָּׁאֵר יִהְיוּ יוֹרְשֵׁי מַלְכוּת הַשָּׁמַיִם אֲשֶׁר לֵאלֹהִים׃","en":"Thus came the voice of the Lord unto me, saying: All who have died without a knowledge of this gospel, who would have received it if they had been permitted to tarry, shall be heirs of the celestial kingdom of God;"},{"d":"2029-12-06","ref":"D&C 138:14","b":"D&C","c":138,"v":14,"he":"כׇּל אֵלֶּה עָזְבוּ אֶת־חַיֵּי הַבָּשָׂר בְּתִקְוָה חֲזָקָה לִתְחִיָּה נִכְבָּדָה בְּחֶסֶד אֱלֹהִים הָאָב וּבְנוֹ הַיָּחִיד יֵשׁוּעַ הַמָּשִׁיחַ׃","en":"All these had departed the mortal life, firm in the hope of a glorious resurrection, through the grace of God the Father and his Only Begotten Son, Jesus Christ."},{"d":"2029-12-07","ref":"D&C 138:17","b":"D&C","c":138,"v":17,"he":"עֲפַר יְשֵׁנֵיהֶם עָתִיד לָשׁוּב לְמִתְכֻּנְתּוֹ הַשְּׁלֵמָה עֶצֶם אֶל עַצְמוֹ וְעָלָיו גִּידִים וּבָשָׂר הָרוּחַ וְהַגּוּף לְהֵאָסֵף וְלֹא יִפָּרְדוּ עוֹד לְמַעַן יְקַבְּלוּ מְלֹא הַשִּׂמְחָה׃","en":"Their sleeping dust was to be restored unto its perfect frame, bone to his bone, and the sinews and the flesh upon them, the spirit and the body to be united never again to be divided, that they might receive a fulness of joy."},{"d":"2029-12-08","ref":"D&C 138:23","b":"D&C","c":138,"v":23,"he":"וַיִּשְׂמְחוּ הַקְּדוֹשִׁים בִּגְאֻלָּתָם וַיִּכְרְעוּ בֶרֶךְ וַיַּכִּירוּ בְּבֶן הָאֱלֹהִים כְּגוֹאֲלָם וּמוֹשִׁיעָם מִמָּוֶת וּמִכַּבְלֵי שְׁאוֹל׃","en":"And the saints rejoiced in their redemption, and bowed the knee and acknowledged the Son of God as their Redeemer and Deliverer from death and the chains of hell."},{"d":"2029-12-09","ref":"D&C 138:26","b":"D&C","c":138,"v":26,"he":"וְאַךְ עַל גְּבוּרוֹתָיו וְנִפְלְאוֹתָיו וְהַכְרָזַת הָאֱמֶת בְּכֹחַ וּבִרְשׁוּת גְּדוֹלִים מְעַטִּים הָיוּ הַשּׁוֹמְעִים לְקוֹלוֹ וְהַשְּׂמֵחִים בִּנְכָחוֹ וְהַמְקַבְּלִים יְשׁוּעָה מִיָּדוֹ׃","en":"And yet, notwithstanding his mighty works, and miracles, and proclamation of the truth, in great power and authority, there were but few who hearkened to his voice, and rejoiced in his presence, and received salvation at his hands."}]});
